#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const cp=require('node:child_process');

const SEED_ID='prhm-root-of-trust-typed-bootstrap-helper-refresh-v6';
const TARGET='/opt/prhm-agent-selfmaint-exec/actions/control-plane-typed-bootstrap-transport-v1.js';
const PREIMAGE_SHA='c29846353a4f6e1bdff04cdc213e4db062238e418da6db5a276fb56188939618';
const CANDIDATE_SHA='80ce1b2d3a53d45a750035a2ff5c8c67f1e31695e08fd41c8f980d7c7109725a';
const CANDIDATE_B64='';
const MODE=0o750,UID=0,GID=0;
const BACKUP_ROOT='/var/backups/prhm-root-of-trust-typed-bootstrap-helper-refresh-v6';
const EXEC_SOCKET='/run/prhm-agent-selfmaint-exec/exec.sock';
const ACTION='control_plane_typed_bootstrap_transport_v1';
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const fail=c=>{throw new Error(c)};
function candidateBytes(){const b=Buffer.from(CANDIDATE_B64,'base64');if(sha(b)!==CANDIDATE_SHA)fail('candidate_sha_mismatch');return b}
function validateTargetStat(st){if(!st||typeof st.isFile!=='function'||!st.isFile())fail('target_not_regular');if(typeof st.isSymbolicLink==='function'&&st.isSymbolicLink())fail('target_symlink');if((st.mode&0o777)!==MODE)fail('target_mode_mismatch');if(st.uid!==UID||st.gid!==GID)fail('target_owner_mismatch');return true}
function validateHealth(h){if(!h||h.ok!==true)fail('executor_unhealthy');const a=Array.isArray(h.host_actions_v2)?h.host_actions_v2:[];if(!a.includes(ACTION))fail('executor_action_missing');return true}
function preflight(adapter){
 if(!adapter||typeof adapter!=='object')fail('adapter_required');
 if(adapter.getuid()!==0)fail('root_required');
 validateTargetStat(adapter.stat());
 const before=adapter.hash();
 if(before===CANDIDATE_SHA){validateHealth(adapter.health());return {ok:true,seed_id:SEED_ID,preflight_only:true,already_applied:true,before_sha256:before,after_sha256:before,production_mutation:false,database_mutation:false,application_mutation:false};}
 if(before!==PREIMAGE_SHA)fail('target_sha_mismatch:'+before);
 const c=candidateBytes();adapter.syntax(c);validateHealth(adapter.health());
 return {ok:true,seed_id:SEED_ID,preflight_only:true,already_applied:false,before_sha256:before,after_sha256:CANDIDATE_SHA,production_mutation:false,database_mutation:false,application_mutation:false};
}
function applyWithAdapter(adapter){
 const pf=preflight(adapter);if(pf.already_applied)return {...pf,preflight_only:false,mutation:false,rollback_performed:false,status:'ALREADY_APPLIED'};
 const preimage=adapter.read();const digest=typeof adapter.digest==='function'?adapter.digest(preimage):sha(preimage);if(digest!==PREIMAGE_SHA)fail('preimage_read_mismatch');
 const candidate=candidateBytes();const backup=adapter.backup(preimage);let mutated=false;
 try{
   adapter.atomicReplace(candidate);mutated=true;
   if(adapter.hash()!==CANDIDATE_SHA)fail('postwrite_sha_mismatch');
   adapter.syntax(adapter.read());validateHealth(adapter.health());
   return {ok:true,seed_id:SEED_ID,status:'APPLIED',mutation:true,before_sha256:PREIMAGE_SHA,after_sha256:CANDIDATE_SHA,backup_id:String(backup),rollback_performed:false,database_mutation:false,application_mutation:false,service_restart:false};
 }catch(error){
   if(!mutated)throw error;
   try{adapter.atomicRestore(preimage);if(adapter.hash()!==PREIMAGE_SHA)fail('rollback_sha_mismatch');adapter.syntax(adapter.read());validateHealth(adapter.health());}
   catch(e){throw new Error('apply_failed_rollback_failed:'+String(error.message||error)+':'+String(e.message||e));}
   return {ok:false,seed_id:SEED_ID,status:'FAILED_ROLLED_BACK',error:String(error.message||error),mutation:true,before_sha256:PREIMAGE_SHA,after_sha256:PREIMAGE_SHA,rollback_performed:true,database_mutation:false,application_mutation:false,service_restart:false};
 }
}
function runtimeAdapter(){
 const syntax=bytes=>{const r=cp.spawnSync('/usr/local/bin/prhm-node',['--check','-'],{input:bytes,encoding:null,timeout:10000,maxBuffer:262144,env:{PATH:'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin',LC_ALL:'C',HOME:'/nonexistent'}});if(r.error||r.status!==0)fail('candidate_syntax_invalid')};
 const health=()=>{const r=cp.spawnSync('/usr/bin/curl',['--silent','--show-error','--fail','--unix-socket',EXEC_SOCKET,'http://localhost/health'],{encoding:'utf8',timeout:10000,maxBuffer:262144,env:{PATH:'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin',LC_ALL:'C',HOME:'/nonexistent'}});if(r.error||r.status!==0)fail('executor_health_failed');let j;try{j=JSON.parse(r.stdout)}catch{fail('executor_health_invalid_json')}return j};
 const atomic=(bytes,tag)=>{const st=fs.lstatSync(TARGET);validateTargetStat(st);const dir=path.dirname(TARGET),tmp=path.join(dir,'.'+path.basename(TARGET)+'.'+tag+'-'+process.pid+'-'+Date.now()+'.tmp');let fd;try{fd=fs.openSync(tmp,'wx',MODE);fs.writeFileSync(fd,bytes);fs.fsyncSync(fd);fs.closeSync(fd);fd=undefined;fs.chmodSync(tmp,MODE);fs.chownSync(tmp,UID,GID);fs.renameSync(tmp,TARGET);const dfd=fs.openSync(dir,fs.constants.O_RDONLY|fs.constants.O_DIRECTORY);try{fs.fsyncSync(dfd)}finally{fs.closeSync(dfd)}}catch(e){try{if(fd!==undefined)fs.closeSync(fd)}catch{}try{if(fs.existsSync(tmp))fs.unlinkSync(tmp)}catch{}throw e}};
 return {
  getuid:()=>process.getuid?process.getuid():-1,
  stat:()=>fs.lstatSync(TARGET),hash:()=>sha(fs.readFileSync(TARGET)),read:()=>fs.readFileSync(TARGET),digest:sha,syntax,health,
  backup:(bytes)=>{fs.mkdirSync(BACKUP_ROOT,{recursive:true,mode:0o700});const id=new Date().toISOString().replace(/[^0-9]/g,'').slice(0,14)+'Z';const f=path.join(BACKUP_ROOT,'typed-bootstrap-helper.'+id+'.'+PREIMAGE_SHA+'.bak');fs.writeFileSync(f,bytes,{flag:'wx',mode:0o600});return id},
  atomicReplace:b=>atomic(b,'apply'),atomicRestore:b=>atomic(b,'rollback')
 };
}
function main(argv=process.argv){if(!Array.isArray(argv)||argv.length!==2)fail('unexpected_arguments');const out=applyWithAdapter(runtimeAdapter());process.stdout.write(JSON.stringify(out)+'\n');if(out.ok!==true)process.exitCode=1}
module.exports={SEED_ID,TARGET,PREIMAGE_SHA,CANDIDATE_SHA,MODE,UID,GID,ACTION,candidateBytes,validateTargetStat,validateHealth,preflight,applyWithAdapter,main};
if(require.main===module){try{main()}catch(e){process.stdout.write(JSON.stringify({ok:false,seed_id:SEED_ID,error:String(e.message||e)})+'\n');process.exitCode=1}}
